pub(crate) fn current_review<'a>(
    feedback: &'a serde_json::Value,
    round: u8,
    head: Option<&'a str>,
) -> CurrentReview<'a> {
    let head = head.filter(|_| round == 1);
    let findings = feedback
        .as_array()
        .into_iter()
        .flatten()
        .filter(|finding| {
            finding["kind"] == "review_finding"
                && head.is_some_and(|sha| finding["reviewed_sha"] == sha)
        })
        .collect();
    CurrentReview { head, findings }
}

pub(crate) fn check(reply: &Value, current: crate::findings::CurrentReview<'_>) -> Result<Fixes> {
    let crate::findings::CurrentReview {
        head: reviewed,
        findings,
    } = current;
    let mappings = reply["reproductions"]
        .as_array()
        .cloned()
        .unwrap_or_default();
    if findings.len() != mappings.len() {
        return Err(Error::Invalid(
            "reproductions must cover every current finding",
        ));
    }
    let mut seen = BTreeSet::new();
    let mut checks = Vec::new();
    let mut evidence = Vec::new();
    for mapping in mappings {
        let id = mapping["finding_id"]
            .as_str()
            .ok_or(Error::Invalid("missing finding id"))?;
        let finding = findings
            .iter()
            .find(|finding| finding["id"] == id)
            .ok_or(Error::Invalid("reproduction names an unknown finding"))?;
        if !seen.insert(id.to_owned()) {
            return Err(Error::Invalid("a reproduction repeats a finding"));
        }
        let mut item = json!({"id": id, "report": finding["report"]});
        if let Some(tests) = mapping["tests"].as_array() {
            let tests = tests
                .iter()
                .map(|test| {
                    let test = test
                        .as_str()
                        .ok_or(Error::Invalid("invalid reproducing test"))?;
                    if !exact_pytest_node_id(test) {
                        return Err(Error::Invalid("expected an exact pytest node id"));
                    }
                    Ok(test.to_owned())
                })
                .collect::<Result<Vec<_>>>()?;
            if tests.is_empty() || tests.iter().collect::<BTreeSet<_>>().len() != tests.len() {
                return Err(Error::Invalid("a reproduction needs distinct tests"));
            }
            let proof = mapping
                .get("proof")
                .filter(|proof| {
                    proof["red_message"]
                        .as_str()
                        .is_some_and(|reason| (1..=160).contains(&reason.chars().count()))
                })
                .ok_or(Error::Invalid("a reproduction needs proof.red_message"))?;
            let declaration = serde_json::from_value(proof.clone())
                .map_err(|_| Error::Invalid("a reproduction needs a valid proof declaration"))?;
            item["tests"] = json!(tests);
            item["proof"] = proof.clone();
            checks.push(Check {
                name: format!("reproducing/{id}"),
                kind: Kind::Reproducing,
                tests,
                forcing: None,
                proof: Some(declaration),
                declared_symptom: None,
            });
        } else {
            item["reason"] = mapping["reason"].clone();
        }
        evidence.push(item);
    }
    Ok(Fixes {
        checks,
        evidence: json!({"reviewed_sha": reviewed, "findings": evidence}),
    })
}
fn exact_pytest_node_id(test: &str) -> bool {
    let mut parts = test.split("::");
    let path = parts.next().unwrap_or_default();
    let names = parts.collect::<Vec<_>>();
    !names.is_empty()
        && names.iter().all(|name| !name.is_empty())
        && path.ends_with(".py")
        && !path.starts_with(['/', '-'])
        && !path.split('/').any(|part| part == "..")
        && !path.contains('\\')
        && !test.contains('\0')
}

pub(crate) fn criteria(
    store: &mut Store,
    snapshot: &tl3_store::Snapshot,
    node: tl3_kernel::NodeId,
) -> Result<Value> {
    let goals = crate::goals::load(snapshot, node)?.ok_or(Error::Invalid("review needs goals"))?;
    let node = node.0.to_string();
    let materials = store
        .worker_materials(&node)?
        .ok_or(Error::Invalid("review materials missing"))?;
    let mut rules = materials
        .get("standing_rules")
        .cloned()
        .unwrap_or(json!([]));
    let rules_list = rules
        .as_array_mut()
        .ok_or(Error::Invalid("standing rules must be a list"))?;
    rules_list.retain(|rule| rule["id"] != REPORT_RULE && rule["id"] != SCOPE_RULE);
    rules_list.push(json!({"id": REPORT_RULE, "description": "Protect test reports. Block code that writes directly to the test process's file descriptors, replaces its output streams, emits text shaped like test-report events, or reaches into pytest hooks, plugins, reporter or configuration internals. Ordinary output from the program under test is allowed. In-process report custody is accepted for slice one."}));
    rules_list.push(json!({"id": SCOPE_RULE, "description": "Keep edits within the supplied request goals. Block an unrelated edit, including inside a planned file, only when it serves none of the supplied goals. Necessary supporting code and tests are in scope. Imports, test fixtures, docstrings and type hints for new or changed code, formatting the change forces, and small helper refactors the change needs are in scope. When unsure whether an edit serves the goals, record a non-blocking finding instead of blocking. Cite this standing rule, identify the unrelated hunk and quote a whole changed diff line from that hunk on its own line in evidence, including its leading plus or minus, from scope_diff when supplied or otherwise diff. Explain why the hunk serves no supplied goal. The quoted changed content must have at least 8 non-whitespace characters; otherwise record a non-blocking finding. Do not invent goals or demand additional work."}));
    Ok(json!({"goals": goals, "standing_rules": rules}))
}
